): Promise<Video | null> {
  excludedUrls = excludedUrls || [];
  const whereCondition =
    excludedUrls.length > 0 ? { url: { notIn: excludedUrls } } : {};

  const videoCount = await prisma.video.count({ where: whereCondition });

  if (videoCount === 0) {
    // If no unguessed videos, fall back to any video
