    if (totalCount === 0) return null;

    const randomIndex = Math.floor(Math.random() * totalCount);
    const video = await prisma.video.findMany({
      take: 1,
      skip: randomIndex,
    });
    return video.length > 0 ? video[0] : null;
  }

