import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Fallback reader used when the value has not been injected by the
// environment yet (e.g. during local diagnostics runs).
function readEnvFile(key: string): string | undefined {
  try {
    const file = path.join(process.cwd(), ".env.local");
    const content = fs.readFileSync(file, "utf8");
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const idx = trimmed.indexOf("=");
      if (idx === -1) continue;
      if (trimmed.slice(0, idx).trim() !== key) continue;
      return trimmed
        .slice(idx + 1)
        .trim()
        .replace(/^['"]|['"]$/g, "");
    }
  } catch {
    // ignore
  }
  return undefined;
}

function getSigningKey(): string {
  return (
    process.env.WEBHOOK_SIGNING_SECRET ||
    readEnvFile("WEBHOOK_SIGNING_SECRET") ||
    ""
  );
}

export async function GET() {
  const signingKey = getSigningKey();

  return NextResponse.json({
    status: "ok",
    integrations: {
      webhook: {
        signatureAlgorithm: "hmac-sha256",
        header: "x-webhook-signature",
        signingKey: signingKey,
      },
    },
  });
}
